const input = $json;

const traceId = String(input.traceId ?? '').trim();
const channel = String(input.channel ?? '').trim();
const sender = String(input.sender ?? '').trim();
const message = String(input.message ?? '').trim();
const intent = String(input.intent ?? '').trim().toUpperCase();

const fechaInicio = String(input.fecha_inicio ?? '').trim() || null;
const fechaFin = String(input.fecha_fin ?? '').trim() || null;
const tipoFecha = String(input.tipo ?? (fechaInicio ? 'una_noche' : 'sin_fechas')).trim();
const categoria = input.categoria ? String(input.categoria).trim().toUpperCase() : null;
const ocupacion = Number(input.ocupacion ?? 1) || 1;
const pasajero = String(input.pasajero ?? '').trim() || null;

const payload = {
  fechas: {
    tipo: tipoFecha,
    fecha_inicio: fechaInicio,
    fecha_fin: fechaFin,
    categoria,
    ocupacion,
    pasajero
  }
};

let valid = true;
const errors = [];

if (!traceId) { valid = false; errors.push('Falta traceId'); }
if (!channel) { valid = false; errors.push('Falta channel'); }
if (!sender) { valid = false; errors.push('Falta sender'); }
if (!message) { valid = false; errors.push('Falta message'); }

if (intent !== 'RESERVA') {
  valid = false;
  errors.push('Intent invalido para Worker Reserva');
}

return {
  json: {
    traceId,
    timestamp: new Date().toISOString(),

    channel,
    sender,
    message,
    intent,

    payload,

    validation: {
      valid,
      errors
    }
  }
};

// 04b - Parsear Sheets (Reserva)
// Convierte la respuesta de batchGet (arrays) a objetos, para 3 hojas

const response = $json;
const ranges = response.valueRanges ?? [];

const rowsToObjects = (values) => {
  if (!values || values.length < 2) return [];
  const headers = values[0].map(h => String(h).trim().toLowerCase());
  return values.slice(1).map(row => {
    const obj = {};
    headers.forEach((h, i) => {
      obj[h] = row[i] ?? null;
    });
    return obj;
  });
};

const dispRange = ranges.find(r =>
  String(r.range ?? '').toUpperCase().startsWith('DISPONIBILIDAD')
);
const tarRange = ranges.find(r =>
  String(r.range ?? '').toUpperCase().startsWith('TARIFAS')
);
const resRange = ranges.find(r =>
  String(r.range ?? '').toUpperCase().startsWith('RESERVAS')
);

const disponibilidad = rowsToObjects(dispRange?.values ?? []);
const tarifas = rowsToObjects(tarRange?.values ?? []);
const reservas = rowsToObjects(resRange?.values ?? []);

return {
  json: {
    disponibilidad,
    tarifas,
    reservas,
    _meta: {
      disponibilidadRows: disponibilidad.length,
      tarifasRows: tarifas.length,
      reservasRows: reservas.length
    }
  }
};

const input = $json;

return {
  json: {
    status: 'RECHAZADO',
    approved: false,
    response: null,

    error: {
      code: 'INVALID_WORKER_INPUT',
      message: 'La entrada recibida por el Worker de Reserva no cumple con los campos requeridos.',
      details: input.validation?.errors ?? []
    },

    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    worker: {
      workflow: 'WF_WORKER_RESERVA',
      stage: 'VALIDACION_ENTRADA'
    }
  }
};

// 05 - Asignar y Preparar Reserva

const sheets = $('04b - Parsear Sheets').first().json;
const ctx = $('02 - Validar Entrada').first().json;

const disponibilidad = sheets.disponibilidad || [];
const tarifasRows = sheets.tarifas || [];
const reservas = sheets.reservas || [];

// ---------- Utilidades ----------
const toISO = (v) => {
  if (v === null || v === undefined || v === '') return null;
  const s = String(v).trim();
  let m = s.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) return m[1] + '-' + m[2] + '-' + m[3];
  m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (m) return m[3] + '-' + m[2].padStart(2, '0') + '-' + m[1].padStart(2, '0');
  return null;
};

const addDays = (iso, n) => {
  const d = new Date(iso + 'T00:00:00Z');
  d.setUTCDate(d.getUTCDate() + n);
  return d.toISOString().slice(0, 10);
};

const categoriaDeHabitacion = (id) => {
  const prefijo = String(id).split('-')[0].toUpperCase();
  const mapa = { STD: 'STANDARD', SUP: 'SUPERIOR', PRE: 'PREMIUM' };
  return mapa[prefijo] || null;
};

// ---------- Datos del payload ----------
const fechas = (ctx.payload && ctx.payload.fechas) ? ctx.payload.fechas : {};
const fechaInicio = toISO(fechas.fecha_inicio);
const fechaFin = toISO(fechas.fecha_fin);
const categoriaSolicitada = fechas.categoria || null;
const ocupacion = Number(fechas.ocupacion || 1) || 1;
const tipoFecha = fechas.tipo || 'sin_fechas';
const pasajero = fechas.pasajero || '';

const hoy = new Date(Date.now() - 3 * 60 * 60 * 1000).toISOString().slice(0, 10);

// ---------- IDEMPOTENCIA ----------
const reservaExistente = reservas.find(r =>
  String(r.trace_id || '').trim() === String(ctx.traceId).trim()
);

if (reservaExistente) {
  return [{
    json: {
      traceId: ctx.traceId,
      timestamp: ctx.timestamp,
      channel: ctx.channel,
      sender: ctx.sender,
      message: ctx.message,
      intent: ctx.intent,
      payload: {
        fechas: {
          tipo: tipoFecha,
          fecha_inicio: fechaInicio,
          fecha_fin: fechaFin,
          categoria: categoriaSolicitada,
          ocupacion: ocupacion,
          pasajero: pasajero
        }
      },
      result: {
        faltanFechas: false,
        fechaPasada: false,
        fechaInicio: fechaInicio,
        fechaFin: fechaFin,
        cantidadNoches: 0,
        ocupacion: ocupacion,
        categoriaSolicitada: categoriaSolicitada,
        fechasSinDatos: [],
        habitacionesDisponibles: [],
        habitacionesBloqueadas: [],
        habitacionesAsignables: [],
        categoriasAlternativas: [],
        asignacion: {
          habitacion_id: reservaExistente.habitacion_id || null,
          categoria: categoriaDeHabitacion(reservaExistente.habitacion_id),
          reserva_id: reservaExistente.reserva_id || null,
          estado: reservaExistente.estado || null
        },
        motivoSinAsignacion: 'RESERVA_DUPLICADA',
        reservaPendiente: null,
        reservaExistente: {
          reserva_id: reservaExistente.reserva_id || null,
          habitacion_id: reservaExistente.habitacion_id || null,
          fecha_entrada: reservaExistente.fecha_entrada || null,
          fecha_salida: reservaExistente.fecha_salida || null,
          estado: reservaExistente.estado || null
        }
      }
    }
  }];
}

// ---------- EARLY RETURN: sin fecha ----------
if (!fechaInicio) {
  return [{
    json: {
      traceId: ctx.traceId,
      timestamp: ctx.timestamp,
      channel: ctx.channel,
      sender: ctx.sender,
      message: ctx.message,
      intent: ctx.intent,
      payload: {
        fechas: {
          tipo: tipoFecha,
          fecha_inicio: null,
          fecha_fin: null,
          categoria: categoriaSolicitada,
          ocupacion: ocupacion,
          pasajero: pasajero
        }
      },
      result: {
        faltanFechas: true,
        fechaPasada: false,
        fechaInicio: null,
        fechaFin: null,
        cantidadNoches: 0,
        ocupacion: ocupacion,
        categoriaSolicitada: categoriaSolicitada,
        fechasSinDatos: [],
        habitacionesDisponibles: [],
        habitacionesBloqueadas: [],
        habitacionesAsignables: [],
        categoriasAlternativas: [],
        asignacion: null,
        motivoSinAsignacion: 'FALTA_FECHA',
        reservaPendiente: null
      }
    }
  }];
}

// ---------- Calcular noches ----------
const noches = [];
if (!fechaFin || fechaFin <= fechaInicio) {
  noches.push(fechaInicio);
} else {
  let d = fechaInicio;
  while (d < fechaFin && noches.length < 90) {
    noches.push(d);
    d = addDays(d, 1);
  }
}

// ---------- Índice de disponibilidad ----------
const estadoPorNoche = {};
const habitaciones = new Set();
for (const r of disponibilidad) {
  const f = toISO(r.fecha);
  const id = String(r.habitacion_id || '').trim();
  if (!f || !id) continue;
  habitaciones.add(id);
  if (!estadoPorNoche[f]) estadoPorNoche[f] = {};
  estadoPorNoche[f][id] = String(r.estado || '').trim().toUpperCase();
}

const fechasSinDatos = noches.filter(n => !estadoPorNoche[n]);
const habitacionesDisponibles = Array.from(habitaciones).filter(id => {
  if (noches.length === 0) return false;
  return noches.every(n => estadoPorNoche[n] && estadoPorNoche[n][id] === 'DISPONIBLE');
});

// ---------- Anti doble-booking ----------
const estadosActivos = ['RESERVADO_PENDIENTE_PAGO', 'RESERVADO_CONFIRMADO'];
const habitacionesBloqueadas = new Set();
for (const r of reservas) {
  const estado = String(r.estado || '').trim().toUpperCase();
  if (estadosActivos.indexOf(estado) === -1) continue;
  const habId = String(r.habitacion_id || '').trim();
  const rIni = toISO(r.fecha_entrada);
  const rFin = toISO(r.fecha_salida);
  if (!habId || !rIni || !rFin) continue;
  for (const n of noches) {
    if (n >= rIni && n < rFin) {
      habitacionesBloqueadas.add(habId);
      break;
    }
  }
}

const habitacionesAsignables = habitacionesDisponibles.filter(
  id => !habitacionesBloqueadas.has(id)
);

// ---------- Tarifas ----------
const tarifasPorCategoria = {};
for (const t of tarifasRows) {
  const cat = String(t.categoria || '').trim().toUpperCase();
  if (!cat) continue;
  tarifasPorCategoria[cat] = {
    precioBase: Number(t.precio_base),
    precioExtra: Number(t.precio_extra_persona),
    capacidadMax: Number(t.capacidad_max)
  };
}

// ---------- Agrupar por categoría ----------
const porCategoria = {};
for (const id of habitacionesAsignables) {
  const cat = categoriaDeHabitacion(id);
  if (!cat) continue;
  if (!porCategoria[cat]) porCategoria[cat] = [];
  porCategoria[cat].push(id);
}

// ---------- Asignación ----------
const prioridad = ['STANDARD', 'SUPERIOR', 'PREMIUM'];
const candidatas = categoriaSolicitada ? [categoriaSolicitada] : prioridad;

let asignacion = null;
let motivoSinAsignacion = null;

for (const cat of candidatas) {
  const t = tarifasPorCategoria[cat];
  if (!t) continue;

  if (ocupacion > t.capacidadMax) {
    if (categoriaSolicitada) {
      motivoSinAsignacion = 'La categoría ' + cat + ' no admite ' + ocupacion + ' personas (máximo ' + t.capacidadMax + ').';
    }
    continue;
  }

  const lista = porCategoria[cat] || [];
  if (lista.length > 0) {
    const precioNoche = t.precioBase + Math.max(0, ocupacion - 1) * t.precioExtra;
    asignacion = {
      habitacion_id: lista[0],
      categoria: cat,
      capacidad_max: t.capacidadMax,
      precio_noche: precioNoche,
      precio_total: precioNoche * Math.max(1, noches.length),
      cantidad_noches: noches.length
    };
    break;
  }
}

// ---------- Motivo de no asignación ----------
if (!asignacion && !motivoSinAsignacion) {
  if (fechaInicio < hoy) {
    motivoSinAsignacion = 'FECHA_PASADA';
  } else if (fechasSinDatos.length > 0) {
    motivoSinAsignacion = 'FUERA_DE_VENTANA';
  } else if (habitacionesDisponibles.length === 0) {
    motivoSinAsignacion = 'SIN_DISPONIBILIDAD';
  } else if (habitacionesAsignables.length === 0) {
    motivoSinAsignacion = 'SIN_DISPONIBILIDAD_ACTIVA';
  } else if (categoriaSolicitada && !porCategoria[categoriaSolicitada]) {
    motivoSinAsignacion = 'CATEGORIA_NO_DISPONIBLE';
  } else {
    motivoSinAsignacion = 'SIN_DISPONIBILIDAD';
  }
}

// ---------- Categorías alternativas ----------
const categoriasAlternativas = Object.keys(porCategoria).map(cat => {
  const t = tarifasPorCategoria[cat];
  const precioNoche = t ? t.precioBase + Math.max(0, ocupacion - 1) * t.precioExtra : null;
  return {
    categoria: cat,
    cantidad: porCategoria[cat].length,
    capacidad_max: t ? t.capacidadMax : null,
    precio_noche: precioNoche,
    apta: t ? ocupacion <= t.capacidadMax : false
  };
});

// ---------- Objeto reservaPendiente ----------
let reservaPendiente = null;
if (asignacion) {
  reservaPendiente = {
    reserva_id: 'RES-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
    trace_id: ctx.traceId,
    habitacion_id: asignacion.habitacion_id,
    fecha_entrada: fechaInicio,
    fecha_salida: fechaFin || fechaInicio,
    estado: 'RESERVADO_PENDIENTE_PAGO',
    pasajero: pasajero,
    contacto: ctx.sender
  };
}

// ---------- Output ----------
return [{
  json: {
    traceId: ctx.traceId,
    timestamp: ctx.timestamp,
    channel: ctx.channel,
    sender: ctx.sender,
    message: ctx.message,
    intent: ctx.intent,

    payload: {
      fechas: {
        tipo: tipoFecha,
        fecha_inicio: fechaInicio,
        fecha_fin: fechaFin,
        categoria: categoriaSolicitada,
        ocupacion: ocupacion,
        pasajero: pasajero
      }
    },

    result: {
      faltanFechas: false,
      fechaPasada: fechaInicio < hoy,
      fechaInicio: fechaInicio,
      fechaFin: fechaFin,
      cantidadNoches: noches.length,
      ocupacion: ocupacion,
      categoriaSolicitada: categoriaSolicitada,

      fechasSinDatos: fechasSinDatos,
      habitacionesDisponibles: habitacionesDisponibles,
      habitacionesBloqueadas: Array.from(habitacionesBloqueadas),
      habitacionesAsignables: habitacionesAsignables,

      categoriasAlternativas: categoriasAlternativas,

      asignacion: asignacion,
      motivoSinAsignacion: motivoSinAsignacion,
      reservaPendiente: reservaPendiente
    }
  }
}];

