const judge = $('07 - Judge').first().json.output;

let traceId = null;
try {
  traceId = $('05 - Asignar y Preparar Reserva').first().json.traceId;
} catch (e) {
  try {
    traceId = $('02 - Validar Entrada').first().json.traceId;
  } catch (e2) {
    traceId = null;
  }
}

return {
  json: {
    status: 'BLOQUEADO',
    approved: false,
    response: null,

    traceId: traceId,
    timestamp: new Date().toISOString(),

    judge: judge,

    escalation: {
      required: true,
      reason: judge && judge.reason ? judge.reason : 'La reserva no superó las validaciones de seguridad.'
    },

    worker: {
      workflow: 'WF_WORKER_RESERVA',
      stage: 'ACTION_GATE'
    }
  }
};

const input = $json;

return {
  json: {
    traceId: input.traceId ?? null,
    timestamp: new Date().toISOString(),

    channel: input.channel,
    recipient: input.sender,

    originalMessage: input.message,
    message: input.response,

    approved: input.approved,

    reservaRegistrada: input.reservaRegistrada ?? null,

    judge: input.judge ?? null,

    worker: {
      workflow: 'WF_WORKER_RESERVA',
      stage: 'DISPATCH'
    },

    dispatch: {
      ready: true,
      source: 'WF_WORKER_RESERVA'
    }
  }
};

const contexto = $('05 - Asignar y Preparar Reserva').first().json;
const respuesta = $('06 - Generar Respuesta').first().json;
const judge = $('07 - Judge').first().json.output;
const reserva = $('09 - Registrar Reserva').first().json;

const texto = String(respuesta.text ?? '').trim();
const responseFinal = texto.length > 0
  ? texto
  : 'No pudimos procesar tu reserva en este momento. Por favor, contactá a recepción.';

return {
  json: {
    traceId: contexto.traceId,
    timestamp: new Date().toISOString(),

    channel: contexto.channel,
    sender: contexto.sender,
    message: contexto.message,
    intent: contexto.intent,

    approved: judge.approved,

    response: responseFinal,

    reservaRegistrada: {
      reserva_id: reserva.reserva_id ?? null,
      habitacion_id: reserva.habitacion_id ?? null,
      estado: reserva.estado ?? null
    },

    judge: judge
  }
};
